changeSet.sql:
delete from file_document_template
where id IN (select file_document_template_id from document_template
            where name = 'EMP Notification Acknowledgement Letter');

delete from document_template
where name = 'EMP Notification Acknowledgement Letter';

delete from file_document_template
where id IN (select file_document_template_id from document_template
             where name = 'EMP Notification Refusal Letter');

delete from document_template
where name = 'EMP Notification Refusal Letter';

INSERT INTO notification_template ( id, name, subject, text) VALUES ( nextval('notification_template_seq'), 'Document generation failed template', 'Problem with a task - Manage your UK ETS reporting', 'Dear regulator,
There was a problem with completing the Review emissions monitoring plan application task.
**Task reference:** ${workflowId}
**Account Name:** ${accountName}
**Account ID:** ${accountBusinessId}
[Sign in to the UK ETS reporting service](${homeUrl}) and select the task in your task list, then select ''Notify Operator of decision'' to try again.
Contact ${competentAuthorityEmail} if you have any questions or need help.
Kind regards, ${competentAuthorityName}' );

            UPDATE notification_template
            SET text = 'Dear Regulator,

There was a problem with completing the Review emissions monitoring plan application task.

**Task reference:** ${workflowId}

**Account Name:** ${accountName}

**Account ID:** ${accountBusinessId}

[Sign in to the UK ETS reporting service](${homeUrl}) and select the task in your task list, then select ''Notify Operator of decision'' to try again.

Contact ${competentAuthorityEmail} if you have any questions or need help.

Kind regards,

${competentAuthorityName}'
            WHERE name = 'Document generation failed template';

rollback.sql:
            UPDATE notification_template
            SET text = 'Dear regulator,

There was a problem with completing the Review emissions monitoring plan application task.

**Task reference:** ${workflowId}

**Account Name:** ${accountName}

