Kind regards, ${competentAuthorityName}'
            WHERE name = 'Document generation failed template';

changeSet.sql:
INSERT INTO notification_template ( id, name, subject, competent_authority, is_managed, last_updated_date, event_trigger, workflow, role_type, text ) VALUES ( nextval('notification_template_seq'), 'EMP approved template', 'An important letter from the Manage your UK ETS reporting service', 'ENGLAND', true, now(), 'EMP approval', 'EMP Issuance, EMP Variation, EMP Variation regulator led, EMP Batch variation', 'OPERATOR', 'Dear ${(accountServiceContactFirstName)!}
Please find attached a communication from your regulator.
You can now [download your approved emissions monitoring plan](${fileLinks[0].url}).
If you have any queries about this letter, please contact your technical officer.
This is an automatic email - please do not reply to this address.') ;

rollback.sql:
delete from notification_template
where name = 'EMP approved template';
and competent_authority = 'ENGLAND';

